update public.categories set image_url = case slug
  when 'smartphones' then 'https://cdn.dummyjson.com/product-images/smartphones/iphone-5s/1.webp'
  when 'tablets' then 'https://cdn.dummyjson.com/product-images/tablets/ipad-mini-2021-starlight/1.webp'
  when 'used' then 'https://cdn.dummyjson.com/product-images/smartphones/iphone-5s/2.webp'
  when 'audio' then 'https://cdn.dummyjson.com/product-images/mobile-accessories/amazon-echo-plus/1.webp'
  when 'chargers' then 'https://cdn.dummyjson.com/product-images/mobile-accessories/apple-airpower-wireless-charger/1.webp'
  when 'cases' then 'https://cdn.dummyjson.com/product-images/mobile-accessories/iphone-12-silicone-case-with-magsafe-plum/1.webp'
  when 'watches' then 'https://cdn.dummyjson.com/product-images/mobile-accessories/apple-watch-series-4-gold/1.webp'
  when 'accessories' then 'https://cdn.dummyjson.com/product-images/mobile-accessories/monopod/1.webp'
end;

select main_image, count(*) from public.products group by main_image order by count(*) desc limit 5;